mapper.delete:
DELETE FROM WC_PRECEDENT_CHUNK
WHERE PRECEDENT_ID =
#{precedentId, jdbcType=BIGINT}

mapper.insert:
INSERT INTO WC_PRECEDENT_CHUNK ( PRECEDENT_ID, CHUNK_NO, CHUNK_TEXT, CHUNK_HASH, EMBEDDING, EMBEDDING_MODEL, EMBEDDING_STATUS, EMBEDDING_ERROR ) VALUES ( #{precedentId, jdbcType=BIGINT}, #{chunkNo, jdbcType=INTEGER}, #{chunkText, jdbcType=CLOB}, #{chunkHash, jdbcType=VARCHAR},
/* * float[]를 Oracle VECTOR(1024, FLOAT32)로 * 변환하는 전용 TypeHandler를 지정한다. */ #{embedding, typeHandler=egovframework.workcare.common.mybatis.OracleFloat32VectorTypeHandler},
#{embeddingModel, jdbcType=VARCHAR}, 'COMPLETED', NULL )

mapper.select:
/* * 1단계: 모든 완료된 청크와 질문 벡터 사이의 * 코사인 거리를 계산한다. */ WITH chunk_distance AS ( SELECT precedent.PRECEDENT_ID, precedent.CASE_NUMBER, precedent.COURT_NAME, precedent.RESULT_TYPE, precedent.CASE_TYPE, precedent.ACCIDENT_DISEASE_TYPE, precedent.TITLE, chunk.CHUNK_NO, chunk.CHUNK_TEXT,
VECTOR_DISTANCE( chunk.EMBEDDING,
/* * 질문 float[]도 저장할 때와 동일한 * Oracle FLOAT32 VECTOR TypeHandler로 바인딩한다. */ #{queryEmbedding, typeHandler=egovframework.workcare.common.mybatis.OracleFloat32VectorTypeHandler},
COSINE ) AS DISTANCE_VALUE
FROM WC_PRECEDENT_CHUNK chunk
INNER JOIN WC_PRECEDENT precedent ON precedent.PRECEDENT_ID = chunk.PRECEDENT_ID
WHERE chunk.EMBEDDING_STATUS = 'COMPLETED' AND chunk.EMBEDDING IS NOT NULL ),
/* * 2단계: 판례별로 거리가 가장 가까운 청크부터 * 순위를 부여한다. */ best_chunk_per_precedent AS ( SELECT chunk_distance.*,
ROW_NUMBER() OVER ( PARTITION BY chunk_distance.PRECEDENT_ID
ORDER BY chunk_distance.DISTANCE_VALUE ASC, chunk_distance.CHUNK_NO ASC ) AS CHUNK_RANK
FROM chunk_distance )
/* * 3단계: 각 판례의 1위 청크만 남긴 뒤 * 전체 거리순으로 정렬하여 상위 판례를 반환한다. */ SELECT ranked_result.PRECEDENT_ID, ranked_result.CASE_NUMBER, ranked_result.COURT_NAME, ranked_result.RESULT_TYPE, ranked_result.CASE_TYPE, ranked_result.ACCIDENT_DISEASE_TYPE, ranked_result.TITLE, ranked_result.CHUNK_NO, ranked_result.CHUNK_TEXT, ranked_result.DISTANCE_VALUE
FROM ( SELECT best_chunk.PRECEDENT_ID, best_chunk.CASE_NUMBER, best_chunk.COURT_NAME, best_chunk.RESULT_TYPE, best_chunk.CASE_TYPE, best_chunk.ACCIDENT_DISEASE_TYPE, best_chunk.TITLE, best_chunk.CHUNK_NO, best_chunk.CHUNK_TEXT, best_chunk.DISTANCE_VALUE
FROM best_chunk_per_precedent best_chunk
WHERE best_chunk.CHUNK_RANK = 1
ORDER BY best_chunk.DISTANCE_VALUE ASC, best_chunk.PRECEDENT_ID ASC ) ranked_result
/* * 반환 건수는 Service가 고정된 작은 값으로 전달한다. */ WHERE ROWNUM <= #{limit, jdbcType=INTEGER}
